css='''
html,body{overflow:hidden}.app{display:grid;grid-template-columns:74px minmax(0,1fr);grid-template-rows:1fr;height:100vh}.rail{grid-row:1}.inventory{display:flex;flex-direction:column;min-width:0;height:100vh;background:#fff}.inventory header{display:flex;align-items:center;justify-content:space-between;padding:30px 34px 22px;min-height:105px}.inventory h1{font-size:28px}.inventory h1 small{font-size:15px}.inventory header p{margin:9px 0 0;color:#8a98ad;font-size:12px}.header-actions{display:flex;gap:10px;align-items:center}.header-actions .btn{font-size:12px}.toolbar{display:flex;gap:12px;padding:0 34px 20px;align-items:center}.toolbar .search{max-width:570px;height:43px}.toolbar .search input{font-size:13px}.toolbar select{border:1px solid #dce4ee;padding:11px;border-radius:6px;color:#617690;background:white;font-size:12px}.toolbar .right{margin-left:auto;font-size:12px;color:#8493a8;display:flex;gap:18px;align-items:center}.status-tabs{display:flex;gap:29px;margin:0 34px;border-bottom:1px solid var(--line);height:44px;align-items:flex-start}.status-tabs button{font-size:13px;padding:0 0 15px;color:#7b8ca3}.status-tabs button.on{border-bottom:2px solid #205eb4;color:#205eb4}.status-tabs small{margin-left:7px;font-size:11px;color:#8b9bb0}.table-area{flex:1;display:flex;min-height:0;min-width:0;padding:23px 34px 0;gap:28px}.table-wrap{flex:1;min-width:0;overflow:auto;scrollbar-width:thin}.inv-table{border-collapse:collapse;width:100%;table-layout:fixed}.inv-table th{text-align:left;font-weight:400;color:#8291a6;font-size:11px;background:#fafbfd;padding:15px 13px;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}.inv-table td{padding:18px 13px;border-bottom:1px solid var(--line);font-size:12px;vertical-align:middle}.inv-table tr[data-index]{cursor:pointer}.inv-table tr[data-index]:hover{background:#f6f9fd}.inv-table tr.selected{background:#edf3fe}.inv-table tr.selected td:first-child{box-shadow:inset 3px 0 #2869cb}.inv-table strong{font-size:14px;font-weight:600}.inv-table small{font-size:11px;color:#8797ad;display:block;margin-top:7px}.inv-table .mono{font-family:Consolas,monospace;font-size:12px;letter-spacing:.1px;color:#3b597f}.inv-table .status{font-size:11px}.inv-table th:first-child,.inv-table td:first-child{width:37px;text-align:center}.inv-table th:nth-child(2){width:14%}.inv-table th:nth-child(3){width:19%}.inv-table th:nth-child(4){width:15%}.inv-table th:nth-child(5){width:12%}.inv-table th:nth-child(6){width:12%}.inv-table th:nth-child(7){width:10%}.inv-table .age strong{font-size:14px;font-weight:500}.inv-table .tick{width:13px;height:13px;border:1px solid #cdd8e7;border-radius:3px;display:inline-block}.inv-table .selected .tick{background:#2766b9;border-color:#2766b9;color:white;font-size:10px}.inv-table .selected .tick:after{content:'✓'}.row-actions{color:#7188a6}.row-actions svg{height:15px;width:15px}.list-meta{display:flex;justify-content:space-between;color:#8c9bb0;font-size:11px;padding:18px 34px;border-bottom:1px solid var(--line)}.detail-strip{margin:0 34px;display:flex;align-items:center;gap:27px;min-height:114px;border-bottom:1px solid var(--line)}.detail-strip img{width:137px;height:83px;object-fit:contain}.detail-strip h3{font-size:21px;margin:0 0 10px}.detail-strip h3 small{font-size:14px;color:#7689a4;font-weight:400;margin-left:7px}.detail-strip .kv{padding-left:27px;border-left:1px solid var(--line)}.detail-strip .kv span{display:block;color:#8a99ae;font-size:11px;margin-bottom:10px}.detail-strip .kv b{font-size:12px;font-weight:500}.detail-strip .strip-actions{display:flex;gap:9px;margin-left:auto}.inventory footer{display:flex;justify-content:space-between;padding:17px 34px;font-size:10px;color:#96a7bf}.inventory footer b{letter-spacing:2px;font-weight:500}.leftfilters{width:215px;flex-shrink:0;border-right:1px solid var(--line);padding-right:24px}.leftfilters h3{font-size:13px;margin:0 0 23px;font-weight:600}.facet-block{border-top:1px solid var(--line);padding-top:20px;margin-bottom:25px}.facet-block h4{color:#8b99ae;font-weight:400;font-size:11px;margin:0 0 15px}.facet-block button{width:100%;display:flex;justify-content:space-between;text-align:left;padding:10px 8px;font-size:12px;color:#667d9c}.facet-block button.on{color:#205eb4;background:#edf3fe;border-radius:4px}.facet-block small{color:#9caabd}.group-title td{background:#f8fafd;color:#5b7394;font-size:12px!important;padding:12px 13px!important}.group-title b{font-weight:600}.group-title small{display:inline;margin-left:12px}.inline-detail td{padding:0!important;border-bottom:1px solid #dce6f4;background:#f9fbfe}.inline-content{display:grid;grid-template-columns:200px 1fr 1fr 1fr;align-items:center;gap:25px;padding:17px 25px}.inline-content img{width:185px;height:110px;object-fit:contain}.inline-content dl{margin:0}.inline-content dt{font-size:10px;color:#8b9bb0;margin-bottom:8px}.inline-content dd{font-size:12px;margin:0 0 14px}.inline-content .inline-actions{display:flex;gap:8px}.age-panel{width:278px;flex-shrink:0;border-left:1px solid var(--line);padding-left:25px}.age-panel h3{font-size:15px;font-weight:600;margin:0 0 9px}.age-panel p{font-size:11px;color:#93a1b5;line-height:1.7;margin:0 0 26px}.age-stat{margin-bottom:23px}.age-stat .row{font-size:12px;margin-bottom:10px;color:#617792}.age-stat strong{font-size:17px;font-weight:500;color:#273e5d}.bar-track{height:5px;background:#edf1f7;border-radius:2px}.bar-track div{height:5px;background:#88a8d2;border-radius:2px}.age-panel .panel-car{border-top:1px solid var(--line);margin-top:30px;padding-top:20px}.panel-car img{width:100%;height:125px;object-fit:contain}.panel-car h4{font-size:20px;margin:10px 0}.panel-car .vin{font-family:Consolas,monospace;font-size:11px}.panel-car .data-row{font-size:11px;min-height:43px}.age-rail{display:flex;gap:0;margin:0 34px 24px;border:1px solid var(--line);border-radius:6px;overflow:hidden}.age-rail button{flex:1;text-align:left;padding:17px 22px;border-right:1px solid var(--line);font-size:12px;color:#7a8da7}.age-rail button:last-child{border:0}.age-rail button.on{background:#f1f6fe}.age-rail strong{display:block;font-size:24px;font-weight:600;color:#244b7e;margin-bottom:6px}.variant-08 .detail-strip{min-height:105px}.variant-09 .inv-table td{padding-top:13px;padding-bottom:13px}.variant-09 .inv-table td small{display:inline;margin-left:7px}.variant-09 .detail-strip{min-height:100px}.variant-10 .inv-table td{padding-top:15px;padding-bottom:15px}.variant-10 .detail-strip{display:none}.variant-10 .table-area{padding-top:20px}.variant-11 .detail-strip{display:none}.variant-11 .inv-table th:nth-child(3){width:23%}.variant-11 .inv-table td{padding-top:19px;padding-bottom:19px}.variant-11 .table-area{padding-top:20px}.variant-11 .status-tabs{display:none}.variant-11 .inv-table th:nth-child(8){width:10%}.variant-11 .inv-table th:nth-child(4){width:13%}.variant-07 .table-area{padding-top:25px}.inventory .page-number{display:flex;gap:16px}.inventory .page-number b{color:#2e5f9b;font-weight:500}.empty-row td{padding:40px;text-align:center;color:#8b9bb0}
'''
css += '.leftfilters,.age-panel{overflow:auto;scrollbar-width:thin}.inv-table td{padding-top:12px;padding-bottom:12px}.variant-11 .inv-table td{padding-top:13px;padding-bottom:13px}.inline-detail td{text-align:left!important}.inv-table th:last-child{width:40px}.variant-10 .inline-content{grid-template-columns:200px 1fr 1fr 1fr}.table-wrap{align-self:stretch}'
js=r'''
const variant='VARIANT';let listQuery='',listStatus='',listModel='',listAge='',listSort=variant==='11'?'age-desc':'default';
const rail=document.querySelector('.rail').outerHTML;
document.body.innerHTML=`<div class="app">${rail}<section class="inventory variant-${variant}"><header><div><h1>Kho xe <small>8</small></h1><p>VinFast Thuận An <span style="margin:0 8px">·</span> Danh sách xe tồn kho</p></div><div class="header-actions"><span style="font-size:11px;color:#8a9ab0;margin-right:15px">Dữ liệu minh họa · 29/10/2026</span><button class="btn" id="columns">${icon('filter')} Cột hiển thị</button><button class="btn" id="export">Xuất danh sách ↗</button></div></header><div class="toolbar"><label class="search">${icon('search')}<input id="search" placeholder="Tìm số VIN, dòng xe, phiên bản, màu ngoại thất…" aria-label="Tìm xe"></label><select id="model-choice" aria-label="Dòng xe"><option value="">Tất cả dòng xe</option>${['VF 3','VF 5','VF 6','VF 7','VF 8','LIMO'].map(s=>`<option>${s}</option>`).join('')}</select><select id="sort-choice" aria-label="Sắp xếp"><option value="default">Thứ tự mặc định</option><option value="age-desc">Tuổi tồn: cao → thấp</option><option value="age-asc">Tuổi tồn: thấp → cao</option></select><div class="right"><span>8 xe · 1 kho</span><span id="view-label">Danh sách</span></div></div><div class="status-tabs" id="status-tabs"></div><div id="age-rail"></div><div class="table-area"><aside class="leftfilters" id="leftfilters" hidden></aside><div class="table-wrap"><table class="inv-table"><thead><tr><th>□</th><th>Dòng xe / Phiên bản</th><th>Số VIN</th><th>Ngoại / Nội thất</th><th>Trạng thái ghép</th><th>Vị trí đỗ</th><th>Ngày nhập kho</th><th>Tuổi tồn ↓</th><th></th></tr></thead><tbody id="inventory-rows"></tbody></table></div><aside class="age-panel" id="age-panel" hidden></aside></div><div class="list-meta"><span id="count">8 / 8 xe</span><div class="page-number"><span>‹</span><b>1</b><span>›</span><span>20 xe / trang</span></div></div><div class="detail-strip" id="detail-strip"></div><footer><span>MẪU VARIANT · TITLE</span><b>© 2026 ORDER MANAGEMENT</b></footer></section></div><div class="toast" id="toast" role="status" hidden></div>`;
function filteredCars(){let items=cars.map((c,i)=>({...c,i})).filter(c=>`${c.model} ${c.version} ${c.vin} ${c.color}`.toLowerCase().includes(listQuery)&&(!listStatus||c.status===listStatus)&&(!listModel||c.model===listModel)&&(!listAge||(listAge==='young'?c.age<=7:listAge==='mid'?c.age>=8&&c.age<=14:c.age>=15)));if(listSort==='age-desc')items.sort((a,b)=>b.age-a.age);if(listSort==='age-asc')items.sort((a,b)=>a.age-b.age);return items}
function rowMarkup(c){return `<tr data-index="${c.i}" class="${c.i===selected?'selected':''}" tabindex="0" aria-selected="${c.i===selected}"><td><span class="tick"></span></td><td><strong>${c.model}</strong><small>${c.version}</small></td><td class="mono">${c.vin}</td><td>${c.color}<small>Black</small></td><td><span class="status" style="--tone:${tone(c.status)}">${c.status}</span></td><td>${c.park}<small>Kho Thuận An</small></td><td>${c.date}</td><td class="age"><strong>${c.age}</strong> <span style="font-size:10px;color:#8b9bb0">ngày</span></td><td class="row-actions">${variant==='10'?(c.i===selected?'⌃':'⌄'):'⋯'}</td></tr>`}
function inlineMarkup(c){return `<tr class="inline-detail"><td colspan="9"><div class="inline-content"><img src="../pictures/${c.image}.webp" alt="${c.model}"><dl><dt>NỘI THẤT / SỐ MÁY</dt><dd>Black · VFCAJB267${210268+c.i}</dd><dt>HỒ SƠ COC</dt><dd>Đã tiếp nhận</dd></dl><dl><dt>PHIẾU NHẬP KHO</dt><dd>PNK-2610-00${128+c.i}</dd><dt>NGƯỜI GIỮ / TVBH</dt><dd>${c.status==='Chưa ghép'?'—':'Lê Thị Hương Trà'}</dd></dl><dl><dt>XE ĐANG CHỌN</dt><dd><b id="model">${c.model}</b> · ${c.version}</dd><div class="inline-actions"><button class="btn" data-demo-action="Nhật ký">Nhật ký</button><button class="btn primary" data-demo-action="Giữ xe (24h)" ${c.status!=='Chưa ghép'?'disabled':''}>Giữ xe (24h)</button></div></dl></div></td></tr>`}
function renderSelection(){const c={...cars[selected],i:selected};if(variant!=='10'&&variant!=='11')$('detail-strip').innerHTML=`<img src="../pictures/${c.image}.webp" alt="${c.model}"><div><h3><span id="model">${c.model}</span><small>${c.version}</small></h3><span style="font-size:11px;color:#7085a0">${c.vin}</span></div><div class="kv"><span>Ngoại / Nội thất</span><b>${c.color} · Black</b></div><div class="kv"><span>Hồ sơ COC</span><b>Đã tiếp nhận</b></div><div class="kv"><span>Phiếu nhập kho</span><b>PNK-2610-00${128+c.i}</b></div><div class="kv"><span>Trạng thái ghép</span><b style="color:${tone(c.status)}">${c.status}</b></div><div class="strip-actions"><button class="btn" data-demo-action="Nhật ký">Xem nhật ký</button><button class="btn primary" data-demo-action="Giữ xe (24h)" ${c.status!=='Chưa ghép'?'disabled':''}>Giữ xe (24h)</button></div>`;
if(variant==='11')$('age-panel').innerHTML=`<h3>Phân bố tuổi tồn</h3><p>Cùng 8 xe minh họa, phân nhóm theo số ngày nhập kho.</p>${[['0–7 ngày',3,38],['8–14 ngày',3,38],['Từ 15 ngày',2,25]].map(g=>`<div class="age-stat"><div class="row"><span>${g[0]}</span><strong>${g[1]} xe</strong></div><div class="bar-track"><div style="width:${g[2]}%"></div></div></div>`).join('')}<div class="panel-car"><h3>Xe đang chọn</h3><img src="../pictures/${c.image}.webp" alt="${c.model}"><h4><span id="model">${c.model}</span> <small style="font-weight:400;color:#8294ad">${c.version}</small></h4><div class="vin">${c.vin}</div><div class="data-row"><span>Vị trí đỗ</span><span>${c.park}</span></div><div class="data-row"><span>Hồ sơ COC</span><span>Đã tiếp nhận</span></div><div class="data-row"><span>Trạng thái</span><span style="color:${tone(c.status)}">${c.status}</span></div><button class="btn primary" style="margin-top:17px;width:100%" data-demo-action="Giữ xe (24h)" ${c.status!=='Chưa ghép'?'disabled':''}>Giữ xe (24h)</button></div>`;
document.querySelectorAll('[data-demo-action]').forEach(b=>b.onclick=()=>toast('Mẫu thao tác '+b.dataset.demoAction+' · Dữ liệu minh họa'))}
function renderList(){const items=filteredCars();let html='';if(variant==='09'){for(const m of ['VF 3','VF 5','VF 6','VF 7','VF 8','LIMO']){const group=items.filter(c=>c.model===m);if(group.length)html+=`<tr class="group-title"><td></td><td colspan="8"><b>${m}</b><small>${group.length} xe · ${group.filter(c=>c.status==='Chưa ghép').length} chưa ghép</small></td></tr>`+group.map(rowMarkup).join('')}}else html=items.map(c=>rowMarkup(c)+(variant==='10'&&c.i===selected?inlineMarkup(c):'')).join('');$('inventory-rows').innerHTML=html||'<tr class="empty-row"><td colspan="9">Không tìm thấy xe phù hợp.</td></tr>';$('count').textContent=`${items.length} / 8 xe · Kho Thuận An`;$('status-tabs').innerHTML=['','Chưa ghép','Đang giữ','Đã ghép'].map(s=>`<button class="${s===listStatus?'on':''}" data-status="${s}">${s||'Tất cả xe'}<small>${s?cars.filter(c=>c.status===s).length:8}</small></button>`).join('');document.querySelectorAll('[data-status]').forEach(b=>b.onclick=()=>{listStatus=b.dataset.status;renderList()});document.querySelectorAll('tr[data-index]').forEach(tr=>{tr.onclick=()=>{selected=Number(tr.dataset.index);renderList()};tr.onkeydown=e=>{if(e.key==='Enter'){selected=Number(tr.dataset.index);renderList()}}});renderSelection()}
$('search').oninput=e=>{listQuery=e.target.value.toLowerCase();renderList()};$('model-choice').onchange=e=>{listModel=e.target.value;renderList()};$('sort-choice').value=listSort;$('sort-choice').onchange=e=>{listSort=e.target.value;renderList()};$('columns').onclick=()=>toast('Colonnes: dòng xe, VIN, màu, trạng thái, vị trí, ngày nhập, tuổi tồn'.replace('Colonnes','Các cột'));$('export').onclick=()=>{const rows=[['Dong xe','Phien ban','VIN','Mau','Trang thai','Vi tri','Ngay nhap','Tuoi ton'],...filteredCars().map(c=>[c.model,c.version,c.vin,c.color,c.status,c.park,c.date,c.age])];const blob=new Blob(['\ufeff'+rows.map(r=>r.join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='kho-xe-minh-hoa.csv';a.click();URL.revokeObjectURL(a.href)};
if(variant==='08'||variant==='09'){const panel=$('leftfilters');panel.hidden=false;panel.innerHTML=`<h3>${variant==='09'?'Danh mục dòng xe':'Bộ lọc kho xe'}</h3><div class="facet-block"><h4>DÒNG XE</h4>${['','VF 3','VF 5','VF 6','VF 7','VF 8','LIMO'].map(m=>`<button data-facet="${m}">${m||'Tất cả dòng xe'}<small>${m?cars.filter(c=>c.model===m).length:8}</small></button>`).join('')}</div><div class="facet-block"><h4>KHO QUẢN LÝ</h4><button class="on">Kho Thuận An <small>8</small></button></div><div class="facet-block"><h4>NGOẠI THẤT</h4><button>White (CE18) <small>8</small></button><h4 style="margin-top:24px">NỘI THẤT</h4><button>Black <small>8</small></button></div>`;panel.querySelectorAll('[data-facet]').forEach(b=>b.onclick=()=>{listModel=b.dataset.facet;$('model-choice').value=listModel;panel.querySelectorAll('[data-facet]').forEach(x=>x.classList.toggle('on',x===b));renderList()})}
if(variant==='11'){$('age-panel').hidden=false;$('age-rail').className='age-rail';$('age-rail').innerHTML=[['','Tất cả xe',8],['young','0–7 ngày',3],['mid','8–14 ngày',3],['old','Từ 15 ngày',2]].map(g=>`<button class="${g[0]===''?'on':''}" data-age="${g[0]}"><strong>${g[2]} <small style="font-size:12px;font-weight:400">xe</small></strong>${g[1]}</button>`).join('');$('age-rail').querySelectorAll('button').forEach(b=>b.onclick=()=>{listAge=b.dataset.age;$('age-rail').querySelectorAll('button').forEach(x=>x.classList.toggle('on',x===b));renderList()})}
if(variant==='09')$('view-label').textContent='Nhóm theo dòng xe';if(variant==='10')$('view-label').textContent='Chi tiết mở ngay trong dòng';if(variant==='11')$('view-label').textContent='Ưu tiên tuổi tồn';document.querySelectorAll('[data-demo]').forEach(b=>b.onclick=()=>toast('Mẫu giao diện Kho xe'));renderList();
'''
titles={'07':'Bảng toàn màn hình','08':'Bảng với bộ lọc bên trái','09':'Danh sách nhóm theo dòng xe','10':'Danh sách mở rộng tại dòng','11':'Danh sách ưu tiên tuổi tồn'}
for n,title in titles.items():
    code=js.replace('VARIANT',n).replace('TITLE',title.upper())
    html=base.replace('</style>',css+'</style>').replace('</body>','<script>'+code+'</script></body>')
    html=html.replace('Kho xe · Mẫu giao diện','Kho xe · Mẫu '+n+' · '+title)
    (root/('public/previews/kho-xe-mau-'+n+'.html')).write_text(html,encoding='utf-8')
    print('Created variant '+n)
